{
  "case_id": "xsu_sg_013_specialist_declaration",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret udelader kildens centrale konstruktion: speciallægeerklæring kan kun indhentes 'i særlige tilfælde'. Det bruger i stedet et generelt kriterium om utilstrækkelige oplysninger. Det tilføjer også uunderstøttede udsagn: at anmodningen 'bør være relevant og nødvendig', at myndigheden 'bør kunne forklare' hvad der mangler, at man kan spørge, hvem der betaler, og at manglende medvirken kan give afslag. Desuden påstår det, at Uddannelses- og Forskningsstyrelsen og ikke Udbetaling Danmark er myndigheden, hvilket strider mod de frosne kilder, der nævner Udbetaling Danmark. Svaret efterlader uklart, hvem der betaler, selvom kilden siger, at Udbetaling Danmark betaler."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Det første kritiske element er kun delvist med, fordi 'i særlige tilfælde' mangler. Det andet kritiske element, de fire eksempelgrupper, er ikke dækket. Svaret nævner ikke symptomernes intensitet og hyppighed, uoverensstemmelse mellem lægeoplysninger og ansøgerens beskrivelse, stor tvivl om behandling og prognose eller dagligt funktionsniveau versus ferieperioder. Det nævner i stedet egne eksempler (funktionsevne, varighed, arbejdsmulighed ved siden af studiet)."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Svaret forsøger at besvare, hvornår der kan anmodes om en speciallægeerklæring, men omdirigerer først spørgsmålet til en anden myndighed. Det giver generiske og delvis opfundne udløsere i stedet for de kildebaserede. Det fylder med praktiske råd om skriftlighed, betaling og konsekvenser, som ikke besvarer spørgsmålet."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, hverken lovbestemmelse, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer uunderstøttet indhold: at Uddannelses- og Forskningsstyrelsen er myndigheden, at eksisterende journaler 'muligvis' kan dække behovet, at myndigheden bør kunne begrunde anmodningen, at man kan bede om begrundelse skriftligt, og at manglende medvirken kan føre til afgørelse på det foreliggende grundlag og afslag. Det tilføjer også eksempler om arbejdsmulighed ved siden af studiet. Intet af dette er støttet af det udleverede materiale."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Det væsentlige forbehold 'i særlige tilfælde' er ikke gengivet. Svaret nævner heller ikke 'stor tvivl' i eksemplerne. Det siger dog, at ikke alle ansøgere skal have en erklæring, hvilket delvis bevarer, at det ikke er automatisk."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: erklæring kan indhentes ved utilstrækkelige oplysninger, den er ikke obligatorisk, og manglende medvirken kan give afgørelse på det foreliggende grundlag. Der er ingen indre modstrid, selv om grundlaget ikke er kildebaseret."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret gør 'særlige tilfælde' til en generel adgang ('når den vurderer, at oplysningerne ikke er tilstrækkelige'). Det bruger 'bør' om krav til myndigheden, uden at kilden har den modalitet. Det omtaler betaling som noget, man skal spørge om, mens kilden fastslår, at Udbetaling Danmark betaler."
    }
  },
  "xhaile_coverage": {
    "A74": {
      "label": "partial",
      "reason": "Svaret siger, at myndigheden kan bede om en speciallægeerklæring, når oplysningerne er utilstrækkelige, hvilket ligger tæt på hovedreglen om utilstrækkelig beskrivelse af art og grad. Det udelader 'i særlige tilfælde' og alle fire eksempler (symptomintensitet/hyppighed, diskrepans, stor tvivl om behandling/prognose, dagligt niveau versus ferie)."
    }
  },
  "overall_notes": "Svaret har en generel og delvis rigtig kerne (utilstrækkelig dokumentation), men udelader 'særlige tilfælde' og de fire vejledningseksempler. Det angiver en forkert myndighed, tilføjer uunderstøttede regler og praktiske råd, og nævner ingen kilder."
}

